def solve(inputs: dict) -> float:
    terms = inputs['terms']

    # Initialize p_(-1) and p_0
    p_prev2 = 1  # p_(-1)
    p_prev1 = terms[0]  # p_0 = a_0

    # Compute using recurrence p_i = a_i * p_(i-1) + p_(i-2)
    for i in range(1, len(terms)):
        p_curr = terms[i] * p_prev1 + p_prev2
        p_prev2 = p_prev1
        p_prev1 = p_curr

    return float(p_prev1)
